import django.utils.timezone
from django.db import migrations, models


def settle_existing_runs(apps, schema_editor):
    # Runs created before the queue existed were never meant to be picked up
    # by a runner: keep completed ones as complete, and park the rest as
    # failed so nothing starts unexpectedly. Requeue them from the admin.
    ModelRun = apps.get_model("model", "ModelRun")
    ModelRun.objects.filter(model_run_completed=True).update(status="complete")
    ModelRun.objects.filter(model_run_completed=False).update(
        status="failed",
        error="Created before the run queue existed; requeue to run it.",
    )


